export default async function (_inputs, context) {
  const inboxes = [];
  let pageNumber = 1;
  while (true) {
    const response = await context.actions.call('helpscout.list_inboxes', { page: pageNumber });
    if (!response || !Array.isArray(response.inboxes) || response.inboxes.some((item) => !item || typeof item !== 'object' || Array.isArray(item))) throw new Error('Help Scout returned an invalid inbox collection');
    inboxes.push(...response.inboxes.slice(0, 50 - inboxes.length));
    if (inboxes.length === 50) return { inboxes };
    const page = response.page;
    if (!page || typeof page !== 'object' || Array.isArray(page) || page.number !== pageNumber || !Number.isSafeInteger(page.totalPages) || page.totalPages < 0 || (page.totalPages === 0 && (pageNumber !== 1 || response.inboxes.length !== 0))) throw new Error('Help Scout pagination metadata is missing or invalid');
    if (pageNumber >= page.totalPages) return { inboxes };
    if (response.inboxes.length === 0) throw new Error('Help Scout returned an empty page before its final page');
    pageNumber++;
  }
}
